steps.raw:
SELECT e.Name
FROM employee e
WHERE e.Employee_ID NOT IN (
    SELECT ev.Employee_ID
    FROM evaluation ev
);

SELECT winner_name, loser_name
FROM matches
WHERE minutes = (SELECT MAX(minutes) FROM matches);

SELECT TV_Channel.Package_Option, TV_Channel.series_name
FROM TV_Channel
WHERE TV_Channel.Hight_definition_TV = [VALUE];

SELECT t.date_of_treatment, p.first_name, p.last_name
FROM Treatments t
JOIN Professionals p ON t.professional_id = p.professional_id;

SELECT d.date_arrived, d.date_departed
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT d.date_arrived, d.date_departed
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;
